function c(u){const s=String(u??"").trim();if(!s)return{ok:!0,empty:!0};let e,n;if(s.startsWith("[")){const t=s.indexOf("]");if(t<0)return{ok:!1,msg:"IPv6 地址需用方括号包裹，如 [::]:443"};if(e=s.slice(1,t),!e||!e.includes(":")||/:::/.test(e)||(e.match(/::/g)||[]).length>1||!/^[0-9a-fA-F:.]+$/.test(e))return{ok:!1,msg:"方括号内应为 IPv6 地址，如 [::]"};const i=e.split(":");if(i.some(l=>l&&!/^[0-9a-fA-F]{1,4}$/.test(l)))return{ok:!1,msg:"方括号内应为 IPv6 地址，如 [::]（每组 1-4 位十六进制）"};const r=i.filter(l=>l==="").length;if(e.includes("::")){const l=i.length-r;if(!(r===3?e==="::":r===1||r===2)||r<3&&l>7)return{ok:!1,msg:"方括号内应为 IPv6 地址，如 [::]（:: 压缩段仅一处）"}}else if(r!==0||i.length!==8)return{ok:!1,msg:"方括号内应为完整 IPv6 地址（8 组，如 [fe80::1] 请写作 [fe80:0:0:0:0:0:0:1] 或含 :: 压缩）"};const o=s.slice(t+1);if(!o.startsWith(":"))return{ok:!1,msg:"格式应为 [IPv6地址]:端口，如 [::]:443"};n=o.slice(1)}else{const t=s.lastIndexOf(":");if(t<=0)if(t===0)e="",n=s.slice(1);else return{ok:!1,msg:"格式应为 host:端口，如 0.0.0.0:80 或 :80"};else e=s.slice(0,t),n=s.slice(t+1);if(e.includes(":"))return{ok:!1,msg:"IPv6 地址需用方括号包裹，如 [::]:443"}}if(!/^\d{1,5}$/.test(n))return{ok:!1,msg:"端口须为 1-65535 的数字"};const f=Number(n);return f<1||f>65535?{ok:!1,msg:"端口须在 1-65535 范围内"}:e&&!e.includes(":")&&!/^[0-9a-zA-Z._-]+$/.test(e)?{ok:!1,msg:"地址仅支持 IP 或主机名"}:{ok:!0,empty:!1,port:f}}export{c as p};
